let db;try{db=JSON.parse(localStorage.getItem(KEY))||seed()}catch{db=seed()}
let storageWarning=false;
function save(){try{localStorage.setItem(KEY,JSON.stringify(db))}catch{if(!storageWarning){storageWarning=true;toast('Browser storage is unavailable. Changes last for this page session.')}}}
function shop(id){return db.merchants.find(m=>m.id===id)||{name:'Pending merchant',initial:'M'}}
function myOrders(){return db.orders.filter(o=>o.merchant==='M001')}
function sums(orders){let gross=orders.reduce((s,o)=>s+o.subtotal,0),paid=orders.reduce((s,o)=>s+o.total,0);return{gross,paid,fee:gross*.05,net:gross*.95}}
function settlement(s){return sums(db.orders.filter(o=>o.settlement===s.id))}
function finance(mid){let list=db.settlements.filter(s=>!mid||s.merchant===mid),paid=list.filter(s=>s.status==='Paid').reduce((n,s)=>n+settlement(s).net,0),pending=list.filter(s=>s.status!=='Paid').reduce((n,s)=>n+settlement(s).net,0);return{paid,pending}}
const date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'—';
function stamp(){return new Date().toLocaleString('en-GB',{timeZone:'Asia/Phnom_Penh',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})}
