function modal(title,body,wide=false){lastFocus=document.activeElement;document.getElementById('modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}</section></div>`;document.body.style.overflow='hidden';document.querySelector('.modal input,.modal button')?.focus()}
function closeModal(){document.getElementById('modal-root').innerHTML='';document.body.style.overflow='';lastFocus?.focus()}
