function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}" class="empty">No matching records. Try another search.</td></tr>`}</tbody></table></div>`}
const cell=(...vals)=>`<tr>${vals.map(v=>`<td>${v}</td>`).join('')}</tr>`;
