const searchBox=(placeholder,value='',scope='list')=>`<div class="search">${icon('search')}<input aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(value)}" data-search="${scope}"></div>`;
function stat(label,value,note,ic='chart'){return `<div class="stat"><div class="stat-top">${label}${icon(ic)}</div><div class="stat-value money">${value}</div><small>${note}</small></div>`}
const manualNote=()=>`<div class="notice">${icon('shield')}<span>Settlement is processed outside the platform. The Master E-Commerce team updates settlement status manually in the system.</span></div>`;
function chart(orders,type='sales'){
 const days=['29 Sep','30 Sep','01 Oct','02 Oct','03 Oct','04 Oct'],dates=['2026-09-29','2026-09-30','2026-10-01','2026-10-02','2026-10-03','2026-10-04'];let vals=dates.map(d=>orders.filter(o=>o.date===d).reduce((n,o)=>n+(type==='orders'?1:o.subtotal),0)),max=Math.max(...vals,1),pts=vals.map((v,i)=>`${45+i*92},${160-v/max*125}`).join(' ');
 return `<svg class="chart" viewBox="0 0 550 210" role="img" aria-label="${type==='orders'?'Order count':'Gross merchandise sales'} for 29 September to 4 October 2026">${[0,1,2,3].map(i=>`<path d="M45 ${35+i*42}H510" stroke="#edf0e8" stroke-dasharray="3 4"/><text x="0" y="${39+i*42}">${type==='orders'?Math.round(max*(1-i/3)):money(max*(1-i/3)).replace('.00','')}</text>`).join('')}<polygon points="45,160 ${pts} 505,160" fill="#edf4eb"/><polyline points="${pts}" fill="none" stroke="#438967" stroke-width="2.8" stroke-linejoin="round"/>${vals.map((v,i)=>`<circle cx="${45+i*92}" cy="${160-v/max*125}" r="4" fill="#fff" stroke="#438967" stroke-width="2"/><text x="${45+i*92}" y="193" text-anchor="middle">${days[i]}</text>`).join('')}</svg>`
}
function chartCard(title,sub,orders,type){return `<div class="card pad"><div class="chart-head"><div><h3>${title}</h3><p>${sub}</p></div><span class="badge">Last 6 days</span></div>${chart(orders,type)}</div>`}
